INSERT INTO "public"."team" ("id", "name", "trait") VALUES (1, 'T1', '첨단 기술과 세련된 도시 이미지를 강조하며, 철갑을 두른 기사를 마스코트로 사용합니다.'), (2, 'Dplus Kia', '거친 파도를 뚫고 나가는 역동적인 에너지를 상징하며, 강력한 공격력을 지향하는 팀 컬러를 가집니다.'), (3, 'Gen.G', '뜨거운 열기와 산업 도시의 끈기를 상징하며, 단단한 수비와 조직력을 바탕으로 하는 팀입니다.'), (4, 'KIWOOM DRX', '천혜의 자연환경과 비상하는 날개를 상징하며, 빠르고 재치 있는 주루 플레이를 선호하는 팀입니다.');